diff --git a/core/operations/recovery.js b/core/operations/recovery.js
index 44df30d..dc857ac 100644
--- a/core/operations/recovery.js
+++ b/core/operations/recovery.js
@@ -33,6 +33,7 @@ function planRecovery(journalDir) {
     attempt_id: entry.attempt_id,
     idempotency_key: entry.idempotency_key,
     effect_class: entry.effect_class,
+    payload_digest: entry.payload_digest,
     state: entry.state,
     ...decisionFor(entry),
   }));
@@ -46,12 +47,24 @@ function planRecovery(journalDir) {
   });
 }

-function recoveryAction(plan, idempotencyKey) {
+/**
+ * `expected` binds the resumed work to the checkpoint it claims to continue. An
+ * idempotency key alone never authorizes a skip: a checkpoint recorded for a
+ * different payload, attempt, or effect class is stale, not evidence.
+ */
+function recoveryAction(plan, idempotencyKey, expected = null) {
   if (plan.journal_status === 'corrupt') return { decision: 'block', reason_code: 'JOURNAL_CORRUPT' };
-  return plan.actions.find((action) => action.idempotency_key === idempotencyKey) || {
-    decision: 'execute',
-    reason_code: 'NO_PRIOR_CHECKPOINT',
-  };
+  const action = plan.actions.find((item) => item.idempotency_key === idempotencyKey);
+  if (!action) return { decision: 'execute', reason_code: 'NO_PRIOR_CHECKPOINT' };
+  if (expected) {
+    if (action.payload_digest !== expected.payloadDigest) {
+      return { decision: 'block', reason_code: 'PAYLOAD_DIGEST_MISMATCH' };
+    }
+    if (action.attempt_id !== expected.attemptId || action.effect_class !== expected.effectClass) {
+      return { decision: 'block', reason_code: 'EFFECT_BINDING_MISMATCH' };
+    }
+  }
+  return action;
 }

 module.exports = Object.freeze({ EFFECT_CLASSES, decisionFor, planRecovery, recoveryAction });
diff --git a/scripts/operation-runner.js b/scripts/operation-runner.js
index b8148d6..ffd1960 100644
--- a/scripts/operation-runner.js
+++ b/scripts/operation-runner.js
@@ -68,7 +68,11 @@ function checkpointInput(options, state, evidenceDigest = null) {
 function executeStepAttempt(options) {
   assertRunnerOptions(options);
   const plan = planRecovery(options.journalDir);
-  const action = recoveryAction(plan, options.idempotencyKey);
+  const action = recoveryAction(plan, options.idempotencyKey, {
+    payloadDigest: options.payloadDigest,
+    attemptId: options.attempt.attempt_id,
+    effectClass: options.effectClass,
+  });
   if (action.decision === 'skip') {
     return Object.freeze({ status: 'completed', execution: 'skipped', reason_code: action.reason_code });
   }
