   assert.deepEqual(readJournal(journalDir).entries.map((entry) => entry.state), ['pending', 'pending', 'completed']);
 });

+test('a checkpoint for different work is stale and never skips the effect', (journalDir) => {
+  let effects = 0;
+  executeStepAttempt(options(journalDir, () => { effects++; return { evidence_digest: EVIDENCE }; }, {
+    effectClass: 'external-nonrepeatable',
+  }));
+  assert.equal(effects, 1);
+  const stale = { effectClass: 'external-nonrepeatable', payloadDigest: sha256Digest({ operation: 'other-work' }) };
+  const mismatched = recoverStepAttempt(options(journalDir, () => { effects++; return { evidence_digest: EVIDENCE }; }, stale));
+  assert.deepEqual(mismatched, { status: 'unknown', execution: 'blocked', reason_code: 'PAYLOAD_DIGEST_MISMATCH' });
+  const rebound = recoverStepAttempt(options(journalDir, () => { effects++; return { evidence_digest: EVIDENCE }; }, {
+    effectClass: 'external-nonrepeatable', attempt: attempt('attempt-demo-2'),
+  }));
+  assert.deepEqual(rebound, { status: 'unknown', execution: 'blocked', reason_code: 'EFFECT_BINDING_MISMATCH' });
+  assert.equal(effects, 1);
+  assert.deepEqual(readJournal(journalDir).entries.map((entry) => entry.state), ['pending', 'completed']);
+});
+
